def transform(grid):
    h, w = len(grid), len(grid[0])
    g = [row[:] for row in grid]
    markers = [(c, grid[0][c]) for c in range(w) if grid[0][c] != 0]
    if len(markers) < 3:
        return g

    (left_c, left_color), (mid_c, mid_color), (right_c, right_color) = markers[:3]

    # The center marker forms a vertical line to the bottom.
    for r in range(h):
        g[r][mid_c] = mid_color

    # The outer markers form vertical lines ending at the rows of their
    # matching isolated markers, with horizontal lines connecting to them.
    for color, col in ((left_color, left_c), (right_color, right_c)):
        points = [(r, c) for r in range(1, h) for c in range(w)
                  if grid[r][c] == color]
        if points:
            r, c = points[0]
            for rr in range(min(r, 0), max(r, 0) + 1):
                g[rr][col] = color
            for cc in range(min(c, col), max(c, col) + 1):
                g[r][cc] = color
    return g
